from collections.abc import Callable

import pytest


def wrapped(job: Callable[[], str]) -> str:
    """Run job and return 'start:' + result + ':end'."""
    return f"start:{job()}:end"


def test_wrapped_basic() -> None:
    def job() -> str:
        return "payload"

    assert wrapped(job) == "start:payload:end"


def test_wrapped_empty_result() -> None:
    assert wrapped(lambda: "") == "start::end"


def test_wrapped_calls_job_once() -> None:
    calls = 0

    def job() -> str:
        nonlocal calls
        calls += 1
        return "done"

    result = wrapped(job)
    assert result == "start:done:end"
    assert calls == 1


def test_wrapped_propagates_exception() -> None:
    def failing_job() -> str:
        raise ValueError("failure")

    with pytest.raises(ValueError, match="failure"):
        wrapped(failing_job)

